def star(M, D, n_iters):
    Mn = M
    for n in range(1, n_iters + 1):
        keep = []
        for x, y in D:
            r, y_hat = Mn.generate(x)
            if y_hat == y:
                keep.append((x, r, y))
            else:
                r2, y2 = Mn.generate(add_hint(x, y))
                if y2 == y:
                    keep.append((x, r2, y))
        Mn = finetune(M, keep)
    return Mn

def make_problem(rng):
    """Three-step word problem: (a * b - c) // d with exact division."""
    a, b = rng.randint(112, 489), rng.randint(13, 47)
    d = rng.choice([3, 4, 6, 7])
    rest = rng.randint(1, (a * b) // d - 1) * d         # leftover, divisible by d
    c = a * b - rest
    name, item = rng.choice(NAMES), rng.choice(ITEMS)
    q = (f"{name} has {b} boxes with {a} {item} in each box. {name} gives away "
         f"{c} {item} and shares the rest equally among {d} friends. "
         f"How many {item} does each friend get?")
    return {"q": q, "a": rest // d, "mid": [a * b, rest]}

def prompt_text(tok, q, hint=None):
    user = q + "\nWork it out in a few short lines of plain text (no LaTeX), then end with a line 'Answer: <number>'."
    if hint is not None:
        user += f"\n(Hint: the correct answer is {hint}.)"
    return tok.apply_chat_template([{"role": "user", "content": user}],
                                   tokenize=False, add_generation_prompt=True)

def extract(text):
    """'Answer: N' if present, else the last \\boxed{N}, else the last integer."""
    for pat in (r"Answer:\s*\**\s*(-?\d+)", r"\\boxed\{\s*(-?\d+)", r"(-?\d+)"):
        m = re.findall(pat, text.replace(",", ""))
        if m:
            return int(m[-1])
    return None
